<?php namespace App\Models; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable; use Illuminate\Database\Eloquent\Factories\HasFactory; class User extends Authenticatable {use HasFactory,Notifiable; protected $fillable=['name','email','password','role']; protected $hidden=['password','remember_token']; protected function casts():array{return ['password'=>'hashed'];} public function projects(){return $this->belongsToMany(Project::class,'project_user');} public function clientProjects(){return $this->hasMany(Project::class,'client_id');} public function tasks(){return $this->hasMany(Task::class,'assignee_id');} public function isAdmin(){return $this->role==='admin';}}
